public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                buflen = -1;
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') ptr++;
            return hasNextByte();
        }

        public int nextInt() {
            if (!hasNext()) return -1;
            int c = readByte();
            while (c <= ' ') {
                c = readByte();
            }
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + c - '0';
                c = readByte();
            }
            return neg ? -res : res;
        }
    }

    // Graph representation using adjacency list (CSR or arrays)
    static int[] head;
    static int[] to;
    static int[] weight;
    static int[] next;
    static int edgeCount = 0;

    static void addEdge(int u, int v, int w) {
        to[edgeCount] = v;
        weight[edgeCount] = w;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        int[] p = new int[k + 1];
        for (int i = 1; i <= k; i++) {
            p[i] = scanner.nextInt();
        }

        int[] u = new int[m];
        int[] v = new int[m];
        int[] t = new int[m];

        // Store half-edges to sort and find unique (station, type) pairs
        // Each half edge: 0 to 2*m - 1
        long[] stationType = new long[2 * m];
        for (int i = 0; i < m; i++) {
            u[i] = scanner.nextInt();
            v[i] = scanner.nextInt();
            t[i] = scanner.nextInt();
            // Encode station and type into long for sorting: station in upper 32 bits, type in lower 32 bits
            stationType[2 * i] = ((long) u[i] << 32) | (long) t[i];
            stationType[2 * i + 1] = ((long) v[i] << 32) | (long) t[i];
        }

        int startNode = scanner.nextInt();
        int endNode = scanner.nextInt();

        Arrays.sort(stationType);

        // Find unique pairs (station, type)
        int uniquePairs = 0;
        for (int i = 0; i < 2 * m; i++) {
            if (i == 0 || stationType[i] != stationType[i - 1]) {
                uniquePairs++;
            }
        }

        long[] uniqueST = new long[uniquePairs];
        int idx = 0;
        for (int i = 0; i < 2 * m; i++) {
            if (i == 0 || stationType[i] != stationType[i - 1]) {
                uniqueST[idx++] = stationType[i];
            }
        }

        // Total nodes:
        // Neutral nodes for stations: 1 to N
        // Layer nodes for (u, T): N + 1 to N + uniquePairs
        int totalNodes = n + uniquePairs + 1;

        // Number of directed edges:
        // Neutral to (u, T): uniquePairs
        // (u, T) to Neutral: uniquePairs
        // Between (u, T) and (v, T) for each original edge: 2 * M
        // Total directed edges = 2 * uniquePairs + 2 * M <= 4 * M + 2 * M = 6 * M
        int maxEdges = 2 * uniquePairs + 2 * m + 10;
        head = new int[totalNodes];
        Arrays.fill(head, -1);
        to = new int[maxEdges];
        weight = new int[maxEdges];
        next = new int[maxEdges];
        edgeCount = 0;

        for (int i = 0; i < uniquePairs; i++) {
            int layerNode = n + 1 + i;
            int station = (int) (uniqueST[i] >>> 32);
            int type = (int) (uniqueST[i] & 0xFFFFFFFFL);

            // Neutral to layer node: cost P[type]
            addEdge(station, layerNode, p[type]);
            // Layer node to neutral: cost 0
            addEdge(layerNode, station, 0);
        }

        // Add original edges between layer nodes
        for (int i = 0; i < m; i++) {
            long keyU = ((long) u[i] << 32) | (long) t[i];
            long keyV = ((long) v[i] << 32) | (long) t[i];

            int idxU = Arrays.binarySearch(uniqueST, keyU);
            int idxV = Arrays.binarySearch(uniqueST, keyV);

            int nodeU = n + 1 + idxU;
            int nodeV = n + 1 + idxV;

            addEdge(nodeU, nodeV, 0);
            addEdge(nodeV, nodeU, 0);
        }

        // Dijkstra's algorithm
        long[] dist = new long[totalNodes];
        Arrays.fill(dist, Long.MAX_VALUE);

        // PriorityQueue storing encoded long: (dist << 24) | u
        // But dist can be up to 1000 * 100000 = 10^8, fits in 32 bits.
        // totalNodes <= 300000, fits in 20 bits.
        // So (dist << 32) | u is completely safe!
        PriorityQueue<Long> pq = new PriorityQueue<>();

        dist[startNode] = 0;
        pq.add((0L << 32) | (long) startNode);

        while (!pq.isEmpty()) {
            long top = pq.poll();
            long d = top >>> 32;
            int curr = (int) (top & 0xFFFFFFFFL);

            if (d > dist[curr]) continue;
            if (curr == endNode) break;

            for (int e = head[curr]; e != -1; e = next[e]) {
                int nxt = to[e];
                long nd = d + weight[e];
                if (nd < dist[nxt]) {
                    dist[nxt] = nd;
                    pq.add((nd << 32) | (long) nxt);
                }
            }
        }

        if (dist[endNode] == Long.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.println(dist[endNode]);
        }
    }
}
